use super::*;
#[test]
fn original_repin_checkpoint_birth_preserves_all_metadata_and_closes_every_prefix(){
 let f:serde_json::Value=serde_json::from_str(include_str!("repin-facts.json")).unwrap();let source:Checkpoint=semio_framework_pack_json::from_json_str(&f["checkpoint"].to_string(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();let id=f["checkpointId"].as_str().unwrap();let input=OriginalRepinCheckpointInput{generation:41,checkpoint:&source,checkpoint_id:id};
 for cut in f["cuts"].as_array().unwrap().iter().map(|n|Some(n.as_u64().unwrap()as usize)).chain([None]){let mut owner=OriginalRepinCheckpointBirth::default();let mut pins=Some(Vec::new());for index in 0..100000{if cut==Some(index)||owner.ready(){break}let d=owner.demands(&input).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};assert!(d.copy_bytes<=4096);for axis in 0..5{let mut denied=g;let n=match axis{0=>1,1=>d.copy_bytes,2=>d.capacity_bytes,3=>d.release_bytes,_=>d.depth};if n==0{continue}match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes-=1,2=>denied.maximum_capacity_bytes-=1,3=>denied.maximum_release_bytes-=1,_=>denied.maximum_depth-=1}let(p,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance(&input,&mut pins,denied).unwrap());assert_eq!(p,Default::default());assert_eq!((h.requested_bytes,h.released_bytes),(0,0));}let(p,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.advance(&input,&mut pins,g).unwrap());assert!(p.fits(g));assert_eq!((h.requested_bytes,h.released_bytes),(p.retained_capacity_bytes,p.released_bytes));assert!(index<99999);}
  if cut.is_none(){let value=owner.prepared().unwrap();let actual:serde_json::Value=serde_json::from_str(&semio_framework_pack_json::to_json_string(value)).unwrap();assert_eq!(actual,f["expected"]);assert!(pins.is_none());}
  while !owner.terminal_is_empty(){let d=owner.close_demands(4096).unwrap();let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth};let(step,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.close_step(4096,g).unwrap());assert!(step.progress().fits(g));assert_eq!((h.requested_bytes,h.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));}
 }
}
